text:
  messageText = encoder.encodeToString().replace(/\s+/g, " ");

  // Crop the end of the text if needed.
  if (messageText.length > 50) {
    messageText = messageText.substr(0, 50);
    if (aCounter == 0) {
      messageText = messageText + Services.locale.ellipsis;
    }
  }

  if (aCounter > 0) {
    messageText = lazy.l10n.formatValueSync("bundled-message-preview", {
      count: aCounter,
      preview: messageText,
    });
  }
}
